"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[4213],{5700(e){e.exports=JSON.parse('{"title":"\uc0c1\ud0dc\uc758 \uc704\uce58\uc5d0\ub108\uc9c0","date":"2025-04-22","coverUrl":"/kudzu-based-bench/assets/notion/4e14955b96be5db2.png","html":"<h2 data-notion-block-id=\\"1dbe548d-8a8e-80a0-9ceb-d7547a3c4ca5\\" id=\\"1dbe548d-8a8e-80a0-9ceb-d7547a3c4ca5\\">\uc0c1\ud0dc\uc758 \uc704\uce58\uc5d0\ub108\uc9c0</h2><a href=\\"https://ondrejvelisek.github.io/avoid-state-synchronization-trap/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://ondrejvelisek.github.io/avoid-state-synchronization-trap/</a><p data-notion-block-id=\\"1dbe548d-8a8e-8033-a5cb-dcb27517a637\\">\uc774\uc804\uc5d0 \uc18c\uac1c \ud588\ub358 <a href=\\"https://ones-to-watch.ethansup.net/news/post/1cfe548d-8a8e-8030-818c-eea9d093d4aa\\"><code>useState()</code></a><a href=\\"https://ones-to-watch.ethansup.net/news/post/1cfe548d-8a8e-8030-818c-eea9d093d4aa\\">\uac00 \uc544\ub2c8\ub77c \uc0c1\ud0dc\uc640 \uce5c\ud574\uc9c0\uae30</a>\ub294 \uc218\ub9ce\uc740 \uacbd\uc6b0\uc5d0 \uc5b4\ub5bb\uac8c \ud574\uc57c\ud558\ub294\uc9c0\ub97c \ubcf4\uc5ec\uc92c\ub2e4\uba74, \uc774 \uae00\uc5d0\uc11c\ub294 \uc0c1\uc704(\ud639\uc740 \ub8e8\ud2b8) \ucef4\ud3ec\ub10c\ud2b8\uc640 \ud558\uc704 \ucef4\ud3ec\ub10c\ud2b8 \uac04\uc5d0 \uc5b4\ub5bb\uac8c \uc0c1\ud0dc\ub97c \uc8fc\uace0 \ubc1b\uc544\uc57c \ud558\ub294\uc9c0, \uc5b4\ub514\uc5d0 \uc704\uce58\ud574\uc57c \ud558\ub294\uc9c0 \uc804\ub7b5\uc744 \uc18c\uac1c\ud558\uace0 \uc7a5\ub2e8\uc810\uc744 \uc54c\uc544\ubcf4\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1dbe548d-8a8e-8026-91e5-ec4b65d9016c\\" id=\\"1dbe548d-8a8e-8026-91e5-ec4b65d9016c\\">Rolldown \ud574\uccb4\ubd84\uc11d</h2><a href=\\"https://www.atriiy.dev/blog/rolldown-module-loader-and-dependency-graph\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.atriiy.dev/blog/rolldown-module-loader-and-dependency-graph</a><p data-notion-block-id=\\"1dbe548d-8a8e-804f-8a16-fb6b26a1c49d\\">Rolldown\uc758 \uc791\ub3d9 \uc6d0\ub9ac\ub97c \ub2e4\uc774\uc5b4\uadf8\ub7a8\uc73c\ub85c \uc798 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. \ub354 \uc798 \uc774\ud574\ud558\uae30 \uc704\ud574\uc11c, \ud604\uc7ac <a href=\\"https://ones-to-watch.ethansup.net/news/post/b251305b-8c2f-4fcc-a159-c495533e1ac4#43fd3b42-d45a-41a4-9c06-7c964fdfe958\\">\ubc88\ub4e4\ub7ec\uc758 \uc5ed\uc0ac</a>\ub098, <a href=\\"https://ones-to-watch.ethansup.net/news/post/f51019e1-e38c-4b60-a636-aab2334f6e8b#b3476a56-0b24-42a0-b655-abe1c6283f73\\">Vite\ub294 \uc5b4\ub5bb\uac8c \uc791\ub3d9\ud558\ub294\uc9c0</a>\ub97c \ubcf4\uc2dc\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1dbe548d-8a8e-80bc-a506-c8b54a2cba87\\" id=\\"1dbe548d-8a8e-80bc-a506-c8b54a2cba87\\">SVG \ud30c\uc77c lazy loading\ud558\uae30..?</h2><a href=\\"https://www.jeantinland.com/blog/lazy-load-svg-icons-with-use-react-js/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.jeantinland.com/blog/lazy-load-svg-icons-with-use-react-js/</a><p data-notion-block-id=\\"1dbe548d-8a8e-80cd-93de-ddf65c82480e\\">svg\uc5d0\uc11c\uc758 <code>&#x3C;use></code>\ud0dc\uadf8\uc640 <code>IntersectionObserver</code>\ub97c \ud1b5\ud574 SVG \ud30c\uc77c\uc744 Lazy loading\ud558\ub294 \uae30\ubc95\uc744 \uad6c\ud604\ud55c \uae00\uc785\ub2c8\ub2e4. \ubb3c\ub860 \ud2b9\uc774 \uc0c1\ud669\uc5d0 \ub300\ud55c \ud574\ub2f5 \uae00\uc774\uc9c0\ub9cc, \uc774\ucc98\ub7fc svg\uc758 \uc5ec\ub7ec \ud0dc\uadf8\ub97c \uc0b4\ud3b4\ubcf4\ub294 \uac83\uc740 <a href=\\"https://ones-to-watch.ethansup.net/news/post/1a7e548d-8a8e-8020-8920-dd3de07abfef#1ade548d-8a8e-80f9-af85-e16f77252e47\\">\uae30\ubc1c\ud55c \uc560\ub2c8\uba54\uc774\uc158 \uad6c\ud604\ud558\uae30</a>\ucc98\ub7fc svg\ub97c \ub354 \uc798 \uc0ac\uc6a9\ud558\ub294\ub370 \ub3c4\uc6c0\uc774 \ub420 \uac83\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1d7e548d-8a8e-808c-9e95-d535fdce1afb\\" id=\\"1d7e548d-8a8e-808c-9e95-d535fdce1afb\\">Next.js\ub294 \uc65c \uc774\ub807\uac8c \ub290\ub824\uc694?</h2><a href=\\"https://www.youtube.com/watch?v=mMQCLQTky34\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.youtube.com/watch?v=mMQCLQTky34</a><p data-notion-block-id=\\"1d7e548d-8a8e-8039-a789-e140ed1e402e\\">Next.js\uc758 RSC \ubc29\uc2dd\uc774 \ub108\ubb34 \ub290\ub9ac\ub2e4\ub294 \ud2b8\uc717(\uacfc \uac04\uc811\uc801\uc73c\ub85c <a href=\\"https://hire.jonasgalvez.com.br/2025/apr/9/fastify-speed/\\">@fastify/react\ubcf4\ub2e4 Next.js\uac00 \ub290\ub9ac\ub2e4\ub294 \ubca4\uce58\ub9c8\ud06c</a> \uae00)\uc5d0 \ubc18\ubc15\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ube44\uc2b7\ud558\uac8c <a href=\\"https://www.youtube.com/watch?v=HbUDiNlU6Yw\\">2023\ub144\uc5d0\ub3c4 \ube44\uc2b7\ud55c \uc601\uc0c1</a>\uc774 \uc788\uc5c8\ub294\ub370, \ud574\ub2f9 \uc601\uc0c1\uc5d0\ub294 fetch\ud558\ub294 \ubc29\uc2dd\uc774 \uae30\uc874\uacfc \ub2e4\ub984\uc744 \uac15\uc870\ud588\ub294\ub370, \uc774 \uc5d0\uc11c\ub294 RSC\uac00 \uc791\ub3d9\ud558\ub294 \ubc29\uc2dd\uacfc \ud568\uaed8 \uae30\uc874 SPA, SSR\uacfc \ub2e4\ub8e8\ub294 \ubc29\uc2dd\uc774 \ub2ec\ub77c\uc838\uc57c \ud558\ub294 \uac83\uc744 \uc124\uba85\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1dbe548d-8a8e-80af-b81a-ef3d1c747e5a\\" id=\\"1dbe548d-8a8e-80af-b81a-ef3d1c747e5a\\">\uc5b4\ub461\ub2e4\uace0 \ubaa8\ub450 \ub2e4\ud06c\ubaa8\ub4dc\uac00 \uc544\ub2c8\ub2e4.</h2><a href=\\"https://www.smashingmagazine.com/2025/04/inclusive-dark-mode-designing-accessible-dark-themes/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.smashingmagazine.com/2025/04/inclusive-dark-mode-designing-accessible-dark-themes/</a><p data-notion-block-id=\\"1dbe548d-8a8e-80b3-8bb4-de117b4ad4e1\\">\ud604\uc7ac \ub9ce\uc740 \uc0ac\uc774\ud2b8\ub4e4\uc774 \ub2e4\ud06c\ubaa8\ub4dc\ub97c \uc9c0\uc6d0\ud558\uc9c0\ub9cc, \ub2e4\ud06c\ubaa8\ub4dc\uc758 \uc811\uadfc\uc131\uc744 \ub193\uce58\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 \ub2e4\ud06c\ubaa8\ub4dc\uc5d0\uc11c \uc911\uc2dc\ud574\uc57c \ud560 \uc811\uadfc\uc131 \uc694\uc18c\ub4e4\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4. \uc5b4\ub290 \uc694\uc18c\ub294 \uc801\uc6a9\ud558\ub294\ub370 \uc2dc\uac04\uc774 \uac78\ub9ac\uaca0\uc9c0\ub9cc, \ubc30\uacbd\uc744 \uc9d9\uc740 \ud68c\uc0c9\uc73c\ub85c \ud574\uc57c \ud55c\ub2e4\ub294 \uc810\uc774\ub098, \uc0c9\uc0c1 \ub300\uc870 \ub3c4\uad6c\ub97c \uc0ac\uc6a9\ud574\ubcf4\ub294 \uac83\uc740 \uc27d\uac8c \uc801\uc6a9\ud574\ubcfc \uc218 \uc788\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"1dbe548d-8a8e-8036-940c-e1140ec99e41\\" id=\\"1dbe548d-8a8e-8036-940c-e1140ec99e41\\"><code>currentColor</code>\uc0ac\uc6a9\ud558\uc9c0 \uc54a\uc744\ub798\uc694?</h2><a href=\\"https://frontendmasters.com/blog/using-currentcolor-in-2025/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://frontendmasters.com/blog/using-currentcolor-in-2025/</a><p data-notion-block-id=\\"1dbe548d-8a8e-8065-9b7c-d3c223c9c1f8\\"><code>currentColor</code>\uc5d0 \ub300\ud55c \uac04\ub2e8\ud55c \uc18c\uac1c\uc640 \uc8fc\uc758\ud574\uc57c \ud560 \uc810\uc740 \ubb34\uc5c7\uc778\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1d7e548d-8a8e-8099-b8a4-e85eb4b439f7\\" id=\\"1d7e548d-8a8e-8099-b8a4-e85eb4b439f7\\">API\uc5d0\uc11c RSC payload\ub85c.</h2><a href=\\"https://overreacted.io/jsx-over-the-wire/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://overreacted.io/jsx-over-the-wire/</a><p data-notion-block-id=\\"1dbe548d-8a8e-809f-a1c0-ded86ebdf285\\">\uc774\uc804\uc5d0 <a href=\\"https://ones-to-watch.ethansup.net/news/post/1cfe548d-8a8e-8030-818c-eea9d093d4aa#1d3e548d-8a8e-805c-ac24-df163854a6f2\\">\ub9ac\uc561\ud2b8 \uba54\uc778\ud14c\uc774\ub108\uac00 \ub9d0\ud558\ub294 RSC \uc544\ud0a4\ud14d\uccd0</a>\uc5d0\uc11c\ub294 \uc544\ud0a4\ud14d\uccd0\uac00 \uc5b4\ub5bb\uac8c \ub9cc\ub4e4\uc5b4\uc838\uc654\ub294\uc9c0\ub97c \uc18c\uac1c\ud588\ub2e4\uba74, \uc774 \uae00\uc5d0\uc11c\ub294 API\ub97c \ub9cc\ub4dc\ub294 \ub300\uc2e0 RSC payload\ub97c \uc0ac\uc6a9\ud558\uae30 \uc6d0\ud558\ub294 \uc774\uc720\ub97c \ub2e8\uacc4\uc5d0 \uac78\uccd0 \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1d9e548d-8a8e-8098-a9c9-eff4a26e23a6\\" id=\\"1d9e548d-8a8e-8098-a9c9-eff4a26e23a6\\">\ub54c\ub85c\ub294, \ub2e4\ub978 \ub77c\uc774\ube0c\ub7ec\ub9ac\uac00 \uc88b\uc744 \uc218\ub3c4 \uc788\ub2e4.</h2><a href=\\"https://blog.swmansion.com/you-might-not-need-react-native-svg-b5c65646d01f\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.swmansion.com/you-might-not-need-react-native-svg-b5c65646d01f</a><p data-notion-block-id=\\"1d9e548d-8a8e-8064-8ae1-ee193764caef\\">\uae00\uc740 <code>react-native-svg</code>\uac00 \uc5b4\ub5a4 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc774\uace0, \uc7a5\ub2e8\uc810\uc744 \ud655\uc2e4\ud788 \ubcf4\uc5ec\uc8fc\uace0, \uadf8\uc5d0 \ub300\ud55c \ub2e4\ub978 \ub300\uccb4 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc774\ub294 \ub2e4\ub978 \ubaa8\ub4e0 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc5d0 \uc801\uc6a9\ub418\ub294 \ub9d0\uc774\ubbc0\ub85c, \ub2e4\ub978 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc5d0\ub3c4 \uc774\ub7f0 \uc0ac\uace0\ub97c \uc801\uc6a9\ud574\ubcfc \uc218 \uc788\uaca0\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1dbe548d-8a8e-8070-8d92-de305ef2b2b9\\" id=\\"1dbe548d-8a8e-8070-8d92-de305ef2b2b9\\">\uc11c\ubc84 \uae30\ubc18 Toast \uba54\uc138\uc9c0 \uad6c\ud604\ud558\uae30</h2><a href=\\"https://buildui.com/posts/toast-messages-in-react-server-components#step-2-creating-the-toast\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://buildui.com/posts/toast-messages-in-react-server-components#step-2-creating-the-toast</a><p data-notion-block-id=\\"1dbe548d-8a8e-8003-968f-e37a4980db8f\\">server action\uacfc cookie\ub97c \uc0ac\uc6a9\ud558\uc5ec Server Action\uacfc \ud568\uaed8 \uc0c8\ub85c\uace0\uce68\ud574\ub3c4 \uc0ac\ub77c\uc9c0\uc9c0 \uc54a\ub294 \uc0c1\ud0dc\uad00\ub9ac\ub97c \uc18c\uac1c\ud558\ub294 \ud29c\ud1a0\ub9ac\uc5bc \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1d8e548d-8a8e-80c5-ad98-f411003f7e68\\" id=\\"1d8e548d-8a8e-80c5-ad98-f411003f7e68\\">JS \ubb38\ubc95 \uc54c\uc544\ubcf4\uae30</h2><a href=\\"https://waspdev.com/articles/2025-04-06/features-that-every-js-developer-must-know-in-2025\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://waspdev.com/articles/2025-04-06/features-that-every-js-developer-must-know-in-2025</a><p data-notion-block-id=\\"1dbe548d-8a8e-80c9-b16d-d72ba98accf2\\">\ub9ce\uc774 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uc9c0\ub9cc, \ucd5c\uc2e0 \ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c\ub294 \ubaa8\ub450 \uc9c0\uc6d0\ud558\ub294 JS \ubb38\ubc95\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"1dbe548d-8a8e-8024-803b-ec034bbd91ce\\" id=\\"1dbe548d-8a8e-8024-803b-ec034bbd91ce\\">\uc0c8 \uce5c\uad6c\ub4e4</h2><a href=\\"https://v4.zod.dev/v4\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://v4.zod.dev/v4</a><p data-notion-block-id=\\"1dbe548d-8a8e-8016-ba91-f15999d5ab88\\">\uc5ec\ub7ec \uc0c8\ub85c\uc6b4 \uae30\ub2a5\uacfc \uc131\ub2a5 \ucd5c\uc801\ud654\uac00 \ud3ec\ud568\ub41c zod 4 beta \ubc30\ud3ec \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://astro.build/blog/astro-570/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://astro.build/blog/astro-570/</a><p data-notion-block-id=\\"1dbe548d-8a8e-8045-884f-d03fdfb2990b\\">\ub124\uc774\ud2f0\ube0c \ud3f0\ud2b8 \ucd5c\uc801\ud654 \uae30\ub2a5\uc744 \ud3ec\ud568\ud55c \uc5c5\ub370\uc774\ud2b8\ud55c Astro 5.7 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://remix.run/blog/faster-lazy-loading\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://remix.run/blog/faster-lazy-loading</a><p data-notion-block-id=\\"1dbe548d-8a8e-80a4-8ae4-ff68089e21c5\\">React Router 7.5\uc5d0\uc11c \ub370\uc774\ud130\ub97c lazy loading\ud558\ub294 \ubc29\uc2dd\uc774 \ubc14\ub00c\uba74\uc11c \ube60\ub974\uac8c \ub418\uc5c8\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://developer.mozilla.org/en-US/blog/h1-element-styles/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://developer.mozilla.org/en-US/blog/h1-element-styles/</a><p data-notion-block-id=\\"1dbe548d-8a8e-80c9-b892-f254685146cb\\">\uc774\uc804\uc5d0\ub294 h1 \ud0dc\uadf8\uc758 \uc2a4\ud0c0\uc77c\uc774 depth\uc5d0 \ub530\ub77c \ubc14\ub00c\uc5c8\uc5c8\ub294\ub370, \uc774\ub97c \ubaa8\ub4e0 \ubaa8\ub358 \ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \ubc14\uafbc\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4. </p><a href=\\"https://una.im/select-updates/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://una.im/select-updates/</a><p data-notion-block-id=\\"1dbe548d-8a8e-80d8-87b9-ee4705ea8f11\\">Chrome\uc5d0\uc11c\ub9cc\uc774\uc9c0\ub9cc, Native <code>&#x3C;select></code>\uc758 \uc694\uc18c\ub4e4\uc744 \ubaa8\ub450 \uc218\uc815\ud560 \uc218 \uc788\uac8c pesudo class\uc744 \uc81c\uacf5\ud55c\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://github.com/tc39/proposal-record-tuple/issues/394\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/tc39/proposal-record-tuple/issues/394</a><p data-notion-block-id=\\"1dbe548d-8a8e-802f-9e82-c0982cdb474b\\">\uc624\ub79c \uae30\uac04\uc744 \ub04c\uc5b4\uc628 Record, Tuple \uae30\ub2a5 \uc81c\uc548\uc774 \ub2eb\ud788\uace0 Composite\uc73c\ub85c \ubc14\ub00c\uc5c8\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://reactnative.dev/docs/native-platform\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://reactnative.dev/docs/native-platform</a><p data-notion-block-id=\\"1dbe548d-8a8e-800c-b5a5-e3cd551f47ed\\">RN\uc5d0\uc11c Native\uae30\ub2a5\ub4e4\uc744 \uc4f0\uae30 \uc704\ud574 Native Components\uc640 Native Modules\ub97c \uc0ac\uc6a9\ud574\uc57c \ud569\ub2c8\ub2e4. \uc774\ub97c \uc798 \uc124\uba85\ud558\ub294 \uacf5\uc2dd\ubb38\uc11c\uac00 \ucd94\uac00\ub418\uc5c8\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://fotis.xyz/posts/the-new-cookie-store-api/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://fotis.xyz/posts/the-new-cookie-store-api/</a><p data-notion-block-id=\\"1dbe548d-8a8e-80a3-b9d1-ca17c506a74d\\">\uc544\uc9c1 \ubaa8\ub4e0 \ubaa8\ub358 \ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \uad6c\ud604\ub418\uc9c4 \uc54a\uc558\uc9c0\ub9cc, Cookie\ub97c \ube44\ub3d9\uae30\uc801\uc73c\ub85c \uad00\ub9ac\ud560 \uc218 \uc788\ub294 API\ub97c \uc0c8\ub85c \ub3c4\uc785\ud55c\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p>"}')}}]);